def mk(sources, gate_mode):
    # gate_mode: 'env' (env>=mx-1), 'off' (all rows >= first), 'none'
    def T(grid, fill=1):
        h,w=len(grid),len(grid[0])
        bgc=Counter(v for row in grid for v in row).most_common(1)[0][0]
        mrks={v for row in grid for v in row}-{bgc}
        out=[row[:] for row in grid]
        r=0
        while r<h:
            if any(v in mrks for v in grid[r]):
                j=r
                while j<h and any(v in mrks for v in grid[j]): j+=1
                env={rr:max(c for c,v in enumerate(grid[rr]) if v in mrks) for rr in range(r,j)}
                mx=max(env.values())
                if mx<w-1:
                    first=min(rr for rr in env if env[rr]==mx)
                    F=set()
                    for rr in range(r,j):
                        if gate_mode=='env' and not(env[rr]>=mx-1 and rr>=first): continue
                        if gate_mode=='off' and rr<first: continue
                        for c in range(mx+1,w):
                            if grid[rr][c]!=bgc: continue
                            okc=False
                            for s in sources:
                                sr,sc=s
