                                if cc2<0 or cc2>=w or rr2<r or rr2>=j: continue
                                if grid[rr2][cc2] in mrks or (rr2,cc2) in F: okc=True; break
                            if okc: out[rr][c]=fill; F.add((rr,c))
                r=j
            else: r+=1
        return out
    return T
