    srcbands=[(r,j) for (r,j) in bs if any(env[rr]==w-1 for rr in range(r,j))]
    if not srcbands or len(srcbands)==len(bs): return out
    srows=[]; salign={}
    for (r,j) in srcbands:
        be=[env[rr] for rr in range(r,j)]; mx=max(be); first=be.index(mx)
        for i,rr in enumerate(range(r,j)):
            ok = (be[i]>=mx-1 and i>=first) if srcsel=='fired' else True
