def band_rows(g):
    bg=Counter(v for row in g for v in row).most_common(1)[0][0]
    mrk={v for row in g for v in row}-{bg}
    h=len(g);w=len(g[0]); out=[]; r=0
    while r<h:
        if any(v in mrk for v in g[r]):
            j=r
            while j<h and any(v in mrk for v in g[j]): j+=1
            out.append((r,j)); r=j
        else: r+=1
    return bg,mrk,out

def ism(g,mrk,r,c):
    return 0<=r<len(g) and 0<=c<len(g[0]) and g[r][c] in mrk

def feats_cell(g,bands,r,c):
    h=len(g);w=len(g[0])
    bg=Counter(v for row in g for v in row).most_common(1)[0][0]
    mrk={v for row in g for v in row}-{bg}
    env={rr:max(cc for cc,v in enumerate(g[rr]) if v in mrk) for rr in range(bands[0][0],bands[-1][1])}
    # my band index & offset
    bi=None;off=None
    for k,(a,b) in enumerate(bands):
        if a<=r<b: bi=k; off=r-a
    ob = None
    if bi is not None and len(bands)>1:
        ok_ = 1-bi
        oa,ob_ = bands[ok_]
        if off < ob_-oa: ob = oa+off
    f={}
    f['self_m']=g[r][c] in mrk
    f['L1']=ism(g,mrk,r,c-1); f['L2']=ism(g,mrk,r,c-2); f['L3']=ism(g,mrk,r,c-3)
    f['U']=ism(g,mrk,r-1,c); f['UL']=ism(g,mrk,r-1,c-1); f['UR']=ism(g,mrk,r-1,c+1)
    f['D']=ism(g,mrk,r+1,c); f['DL']=ism(g,mrk,r+1,c-1); f['DR']=ism(g,mrk,r+1,c+1)
    f['edge']=(c==w-1)
    tip=env[r]
    f['at_tip']=(c==tip); f['gt_tip']=(c>tip); f['lt_tip']=(c<tip)
    mx=max(env.values()); f['at_mx']=(c==mx); f['gt_mx']=(c>mx)
    f['isol']=(not ism(g,mrk,r,c-1)) and (not ism(g,mrk,r,c+1))
    if ob is None:
        f['OB_m']=None;f['OB_L']=None;f['OB_R']=None;f['OB_empty']=None;f['OB_tip']=None
    else:
        f['OB_m']=ism(g,mrk,ob,c);f['OB_L']=ism(g,mrk,ob,c-1);f['OB_R']=ism(g,mrk,ob,c+1)
        f['OB_empty']=not any(ism(g,mrk,ob,cc) for cc in range(w))
        f['OB_tip']=(c==env[ob])
    return f

