def align_shift(src, tgt, mrk):
    # find delta maximizing matches tgt[c]==src[c-delta]; delta in -3..6
    w=len(tgt); best=(-1,0)
    for d in range(-3,7):
        m=0
        for c in range(w):
            sc = c-d
            sv = src[sc] if 0<=sc<w else None
            if sv is not None and (sv in mrk)==(tgt[c] in mrk): m+=1
        if m>best[0]: best=(m,d)
    return best[1]

def transform12(grid, fill=1):
    h,w=len(grid),len(grid[0])
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    mrk={v for row in grid for v in row}-{bg}
    out=[row[:] for row in grid]
    bands=[]; r=0
    while r<h:
        if any(v in mrk for v in grid[r]):
            j=r
            while j<h and any(v in mrk for v in grid[j]): j+=1
            bands.append((r,j)); r=j
        else: r+=1
    if len(bands)<2: return out
    # source band = the one with max tip
    tips=[]
    for (a,b) in bands:
        tips.append(max(max(c for c,v in enumerate(grid[rr]) if v in mrk) for rr in range(a,b)))
    si=tips.index(max(tips))
    ti=1-si
    sa,sb=bands[si]; ta,tb=bands[ti]
    srccol={}
    for k in range(ta-ta, min(sb-sa, tb-ta)):
        pass
    for rr in range(ta,tb):
        off=rr-ta
        srow = sa+off
        if srow>=sb: continue
        src=grid[srow]; tgt=grid[rr]
        tt=max(c for c,v in enumerate(tgt) if v in mrk) if any(v in mrk for v in tgt) else -1
        d=align_shift(src,tgt,mrk)
        for c in range(w):
            if c<=tt: continue
            if tgt[c]!=bg: continue
            sc=c-d
            if 0<=sc<w and src[sc] in mrk:
                out[rr][c]=fill
    return out

