def transform13(grid, fill=1):
    h,w=len(grid),len(grid[0])
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    mrk={v for row in grid for v in row}-{bg}
    out=[row[:] for row in grid]
    bands=[]; r=0
    while r<h:
        if any(v in mrk for v in grid[r]):
            j=r
            while j<h and any(v in mrk for v in grid[j]): j+=1
            bands.append((r,j)); r=j
        else: r+=1
    if len(bands)<2: return out
    tips=[max(max((c for c,v in enumerate(grid[rr]) if v in mrk),default=-1) for rr in range(a,b)) for a,b in bands]
    si=tips.index(max(tips)); ti=1-si
    sa,sb=bands[si]; ta,tb=bands[ti]
    for rr in range(ta,tb):
        tgt=grid[rr]
        tt=max((c for c,v in enumerate(tgt) if v in mrk),default=-1)
        best=(-1,0,0)
        for sr in range(sa,sb):
            src=grid[sr]
            for dg in range(-4,7):
                m=0
                for c in range(w):
                    sc=c-dg
                    if 0<=sc<w and (src[sc] in mrk)==(tgt[c] in mrk): m+=1
                if m>best[0]: best=(m,sr,dg)
        _,sr,dg=best
        src=grid[sr]
        for c in range(w):
            if c<=tt or tgt[c]!=bg: continue
            sc=c-dg
            if 0<=sc<w and src[sc] in mrk: out[rr][c]=fill
    return out

