def band_shift_fill(grid, fill=1, bg=None, marker=None):
    """Row-bands of markers: the band whose rightmost marker reaches furthest is the source; every other band's rows are aligned to it row-by-row and its background cells beyond its tip become fill exactly where the source band (at the best-fitting horizontal shift, ties preferring the smallest |shift|) has a marker."""
